function inventory(root: string): { path: string; sha256: string; mode: number }[] {
  const files: { path: string; sha256: string; mode: number }[] = [];
  function walk(directory: string) {
    for (const name of readdirSync(directory).sort()) {
      if (directory === root && ['.git', 'node_modules'].includes(name)) continue;
      const path = join(directory, name);
      const info = lstatSync(path);
      if (info.isSymbolicLink()) throw new Error('Generation symlink');
      if (info.isDirectory()) walk(path);
      else if (info.isFile() && info.nlink === 1) files.push({ path: relative(root, path), sha256: createHash('sha256').update(readFileSync(path)).digest('hex'), mode: info.mode & 0o777 });
      else throw new Error('Generation alias');
    }
  }
  walk(root);
  return files;
}
export function hotfixModuleOrigin(orchestratorRoot: string, productionRoot: string, modulePath: string, qa: boolean): string | undefined {
  const common = git(productionRoot, 'rev-parse', '--path-format=absolute', '--git-common-dir');
  const control = join(realpathSync(common), 'raf-hotfix');
  const root = dirname(dirname(modulePath));
  if (realpathSync(root) !== root || !['src', 'bin', 'scripts'].includes(relative(root, modulePath).split('/')[0])) return undefined;
  try {
    const state = json(join(control, 'registry.json'));
    const generation = state.generations?.[root];
    if (generation && root.startsWith(join(control, 'generations') + '/') && generation.root === root) {
      if (createHash('sha256').update(JSON.stringify(inventory(root))).digest('hex') !== generation.fingerprint) return undefined;
      return root;
    }
  } catch {}

export async function inventory(root: string, omit = new Set(['.git', 'node_modules'])): Promise<{ path: string; sha256: string; mode: number }[]> {
  const files: { path: string; sha256: string; mode: number }[] = [];
  async function walk(directory: string) {
    for (const name of (await fs.readdir(directory)).sort()) {
      if (directory === root && omit.has(name)) continue;
      const path = join(directory, name);
      const info = await fs.lstat(path);
      if (info.isSymbolicLink()) throw new Error('Snapshot symlink refused: ' + path);
      if (info.isDirectory()) await walk(path);
      else if (info.isFile() && info.nlink === 1) files.push({ path: relative(root, path), sha256: hash(await fs.readFile(path)), mode: info.mode & 0o777 });
      else throw new Error('Snapshot file alias or unsupported type: ' + path);
    }
  }
  await walk(root);
  return files;
}
export async function copyTree(source: string, target: string): Promise<void> {
  await fs.cp(source, target, { recursive: true, dereference: false, errorOnExist: true, force: false, filter: path => !['.git', 'node_modules'].includes(relative(source, path).split(sep)[0]) });
  if (await exists(join(source, 'node_modules'))) await fs.cp(join(source, 'node_modules'), join(target, 'node_modules'), { recursive: true, dereference: true });

async function generation(host: HotfixHost, route: Awaited<ReturnType<typeof mainRoute>>, source: string, commit: string, configurationRoot = join(host.orchestratorRoot, 'conf')): Promise<Generation> {
  const parent = join(route.control, 'generations', randomUUID());
  const root = join(parent, 'raf-main');
  await fs.mkdir(parent, { recursive: true, mode: 0o700 });
  await durable(join(parent, 'ownership.json'), { root, orchestratorRoot: host.orchestratorRoot, repositoryIdentity: route.repositoryIdentity });
  await copyTree(source, root);
  await fs.cp(configurationRoot, join(parent, 'conf'), { recursive: true, dereference: false });
  const files = await inventory(root);
  return { root, commit, fingerprint: hash(JSON.stringify(files)), files };
}
